const listProjectJobs = `-- name: ListProjectJobs :many
SELECT
  j.id, j.project_id, j.kind, j.status, j.progress_json, j.result_json, j.error_json, j.claimed_at, j.started_at, j.completed_at, j.cancel_requested_at, j.expires_at, j.created_at, j.updated_at, j.claim_incarnation, j.artifact_source_owner_id, j.governance_payload_state, j.subject_json, j.creator_user_id, j.can_cancel, j.queue_class, j.retry_count, j.max_attempts, j.next_attempt_at, j.creator_request_id,
  (
    j.artifact_source_owner_id IS NOT NULL
    AND CASE WHEN j.kind = 'research_chat_turn'
      THEN ck_artifact_source_owner_is_lifecycle_readable(
        j.artifact_source_owner_id, j.project_id, 'job', j.id
      )
      ELSE ck_artifact_source_owner_is_readable(
        j.artifact_source_owner_id, j.project_id, 'job', j.id
      )
    END
  )::boolean AS readable
FROM (
  SELECT candidate.id
  FROM jobs candidate
  JOIN projects p ON p.id = candidate.project_id
  JOIN project_memberships m ON m.project_id = candidate.project_id
  WHERE candidate.project_id = $1
    AND m.user_id = $2
    AND m.removed_at IS NULL
    AND p.deleted_at IS NULL
    AND ($3::text = '' OR candidate.kind = $3::text)
    AND (NOT $4::boolean OR candidate.status IN ('queued', 'running', 'canceling'))
    AND (
      NOT $5::boolean
      OR (candidate.created_at, candidate.id) < ($6::timestamptz, $7::uuid)
    )
  ORDER BY candidate.created_at DESC, candidate.id DESC
  LIMIT $8
) AS page
JOIN jobs j ON j.id = page.id
ORDER BY j.created_at DESC, j.id DESC
`

type ListProjectJobsParams struct {
	ProjectID       pgtype.UUID        `json:"project_id"`
	ActorUserID     pgtype.UUID        `json:"actor_user_id"`
	Kind            string             `json:"kind"`
	ActiveOnly      bool               `json:"active_only"`
	HasCursor       bool               `json:"has_cursor"`
	CursorCreatedAt pgtype.Timestamptz `json:"cursor_created_at"`
	CursorID        pgtype.UUID        `json:"cursor_id"`
	LimitCount      int32              `json:"limit_count"`
}

type ListProjectJobsRow struct {
	Job      Job  `json:"job"`
	Readable bool `json:"readable"`
}

// One page of Job candidates in list order (specs/2026-10-28-fast-job-list-and-postgres.md,
// UC2). Tenant predicates, the kind and active filters and the cursor pick the page through
// jobs_project_kind_recent_idx or jobs_project_active_recent_idx; only the rows of the page get
// the read check, and the caller skips the unreadable ones. A Job without an owner is never
// readable and calls no check.
func (q *Queries) ListProjectJobs(ctx context.Context, arg ListProjectJobsParams) ([]ListProjectJobsRow, error) {
	rows, err := q.db.Query(ctx, listProjectJobs,
		arg.ProjectID,
		arg.ActorUserID,
		arg.Kind,
		arg.ActiveOnly,
		arg.HasCursor,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListProjectJobsRow
	for rows.Next() {
		var i ListProjectJobsRow
		if err := rows.Scan(
			&i.Job.ID,
			&i.Job.ProjectID,
			&i.Job.Kind,
			&i.Job.Status,
			&i.Job.ProgressJson,
			&i.Job.ResultJson,
			&i.Job.ErrorJson,
			&i.Job.ClaimedAt,
			&i.Job.StartedAt,
			&i.Job.CompletedAt,
			&i.Job.CancelRequestedAt,
			&i.Job.ExpiresAt,
			&i.Job.CreatedAt,
			&i.Job.UpdatedAt,
			&i.Job.ClaimIncarnation,
			&i.Job.ArtifactSourceOwnerID,
			&i.Job.GovernancePayloadState,
			&i.Job.SubjectJson,
			&i.Job.CreatorUserID,
			&i.Job.CanCancel,
			&i.Job.QueueClass,
			&i.Job.RetryCount,
			&i.Job.MaxAttempts,
			&i.Job.NextAttemptAt,
			&i.Job.CreatorRequestID,
			&i.Readable,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

