const releaseWorkerClaim = `-- name: ReleaseWorkerClaim :one
UPDATE jobs AS job
SET
  status = 'queued',
  progress_json = CASE
    WHEN job.kind = 'import' THEN jsonb_build_object(
      'phase', 'queued',
      'bytesTransferred', job.progress_json->'bytesTransferred',
      'bytesTotal', job.progress_json->'bytesTotal',
      'queuedAt', job.progress_json->'queuedAt',
      'transferredAt', job.progress_json->'transferredAt'
    )
    WHEN job.kind = 'research_chat_turn' THEN jsonb_build_object('phase', 'waiting')
    ELSE job.progress_json
  END,
  claim_incarnation = job.claim_incarnation + 1,
  claimed_at = NULL,
  next_attempt_at = clock_timestamp(),
  updated_at = clock_timestamp()
FROM projects AS project
WHERE job.project_id = $1
  AND job.id = $2
  AND job.claim_incarnation = $3
  AND job.status = 'running'
  AND job.cancel_requested_at IS NULL
  AND project.id = job.project_id
  AND project.deleted_at IS NULL
  AND CASE WHEN job.kind = 'research_chat_turn' THEN ck_artifact_source_owner_is_lifecycle_readable(
    job.artifact_source_owner_id, job.project_id, 'job', job.id
  ) ELSE ck_artifact_source_owner_is_readable(
    job.artifact_source_owner_id, job.project_id, 'job', job.id
  ) END
RETURNING job.id, job.project_id, job.kind, job.status, job.progress_json, job.result_json, job.error_json, job.claimed_at, job.started_at, job.completed_at, job.cancel_requested_at, job.expires_at, job.created_at, job.updated_at, job.claim_incarnation, job.artifact_source_owner_id, job.governance_payload_state, job.subject_json, job.creator_user_id, job.can_cancel, job.queue_class, job.retry_count, job.max_attempts, job.next_attempt_at, job.creator_request_id
`

type ReleaseWorkerClaimParams struct {
	ProjectID        pgtype.UUID `json:"project_id"`
	JobID            pgtype.UUID `json:"job_id"`
	ClaimIncarnation int64       `json:"claim_incarnation"`
}

// A graceful stop returns the exact running claim to the queue without spending an attempt;
// the next claim increments claim_incarnation again.
func (q *Queries) ReleaseWorkerClaim(ctx context.Context, arg ReleaseWorkerClaimParams) (Job, error) {
	row := q.db.QueryRow(ctx, releaseWorkerClaim, arg.ProjectID, arg.JobID, arg.ClaimIncarnation)
	var i Job
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.Kind,
		&i.Status,
		&i.ProgressJson,
		&i.ResultJson,
		&i.ErrorJson,
		&i.ClaimedAt,
		&i.StartedAt,
		&i.CompletedAt,
		&i.CancelRequestedAt,
		&i.ExpiresAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ClaimIncarnation,
		&i.ArtifactSourceOwnerID,
		&i.GovernancePayloadState,
		&i.SubjectJson,
		&i.CreatorUserID,
		&i.CanCancel,
		&i.QueueClass,
		&i.RetryCount,
		&i.MaxAttempts,
		&i.NextAttemptAt,
		&i.CreatorRequestID,
	)
	return i, err
}

